struct Trie {
    vector<array<int, 26>> nx = vector<array<int, 26>>(1);  // 0 is the root
    vector<bool> isEnd = vector<bool>(1, false);
    int step(int u, char ch, bool make) {
        int c = ch - 'a';
        if (!nx[u][c] && make) {
            nx.push_back({}); isEnd.push_back(false);
            nx[u][c] = nx.size() - 1;
        }
        return nx[u][c] ? nx[u][c] : -1;      // -1: no such child
    }

    void insert(const string& w) {
        int u = 0;
        for (char ch : w) u = step(u, ch, true);
        isEnd[u] = true;
    }
    bool has(const string& w) {
        int u = 0;
        for (char ch : w) if ((u = step(u, ch, false)) < 0) return false;
        return isEnd[u];
    }
    bool startsWith(const string& p) {
        int u = 0;
        for (char ch : p) if ((u = step(u, ch, false)) < 0) return false;
        return true;
    }
};
